CSS=r'''
:root{--brand:#536cff;--brand-dark:#4057e8;--canvas:#f6f7fb;--surface:#fff;--soft:#fafbfe;--text:#20222a;--muted:#858a98;--border:#e5e8f0;--success:#2f8f74;--danger:#b45f55;--shadow:0 14px 40px rgba(36,42,68,.08)}*{box-sizing:border-box}html{background:var(--canvas)}body{margin:0;background:var(--canvas);color:var(--text);height:100vh;overflow:hidden;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}button,input,textarea{font:inherit}.app-shell{height:100vh;overflow:hidden}.topbar{height:68px;display:flex;align-items:center;gap:28px;padding:0 28px;background:#fff;border-bottom:1px solid var(--border)}.brand{display:flex;align-items:center;gap:10px;color:var(--text);font-weight:900;text-decoration:none;white-space:nowrap}.brand-mark{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:var(--brand);color:#fff;font-size:13px;box-shadow:0 8px 18px rgba(83,108,255,.24)}.topnav{display:flex;align-items:center;gap:6px;min-width:0;overflow-x:auto;scrollbar-width:none}.topnav-link{height:38px;display:flex;align-items:center;padding:0 13px;border-radius:10px;color:#707482;text-decoration:none;font-size:13px;font-weight:760;white-space:nowrap}.topnav-link.active{background:#eef1ff;color:var(--brand)}.topbar-tools{margin-left:auto;display:flex;gap:8px}.topbar-action{min-height:38px;border:1px solid var(--border);border-radius:11px;background:#fff;padding:0 13px;color:#565b69;font-weight:760;cursor:pointer}.studio-grid{display:grid;grid-template-columns:minmax(360px,460px) minmax(0,1fr);gap:22px;max-width:1540px;height:calc(100vh - 68px);margin:auto;padding:22px 24px 20px}.creation-pane{display:flex;flex-direction:column;min-width:0;min-height:0;background:#fff;border:1px solid var(--border);border-radius:22px;overflow:hidden;box-shadow:var(--shadow)}.creation-scroll{flex:1;min-height:0;overflow:auto;padding:20px}.creation-footer{padding:12px 20px 18px;border-top:1px solid var(--border);background:#fff}.eyebrow{display:block;margin-bottom:4px;color:var(--brand);font-size:10px;font-weight:900;letter-spacing:.13em}.pane-heading h1{margin:0;font-size:22px}.provider-note{margin:12px 0 16px;padding:11px 12px;border:1px solid #e1e5f4;border-radius:11px;background:#f8f9ff;color:#676d7d;font-size:11px;line-height:1.6}.field-label{display:block;margin:14px 0 7px;color:#666c79;font-size:12px;font-weight:850}.drop{position:relative;min-height:210px;display:flex;flex-direction:column;align-items:center;justify-content:center;border:2px dashed #d9deeb;border-radius:15px;background:#fafbfe;color:#818795;text-align:center;cursor:pointer;overflow:hidden}.drop.drag{border-color:var(--brand);background:#f4f6ff}.drop strong{display:block;color:#525968;margin-bottom:5px}.drop small{font-size:11px}.drop img{display:none;max-width:100%;max-height:300px;object-fit:contain}.drop.has-image{padding:8px}.drop.has-image img{display:block}.drop.has-image .drop-copy{display:none}#sourceFile{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.upload-state{min-height:20px;margin-top:7px;color:#737987;font-size:11px;word-break:break-all}.upload-state.ok{color:var(--success)}.upload-state.err{color:var(--danger)}textarea{display:block;width:100%;min-height:104px;padding:11px 12px;border:1px solid var(--border);border-radius:11px;background:#fff;color:var(--text);resize:vertical}.hint{margin-top:6px;color:var(--muted);font-size:11px;line-height:1.55}.primary{width:100%;min-height:52px;border:1px solid #aeb9ff;border-radius:12px;background:#fff;color:#4057e8;font-weight:850;cursor:pointer;transition:background .18s,color .18s,border-color .18s}.primary:hover{background:#f6f7ff}.primary[disabled]{cursor:not-allowed;opacity:.62}.primary[aria-busy="true"]{background:#536cff;color:#fff;border-color:#536cff}.status{min-height:18px;margin-top:8px;color:#687080;font-size:11px;line-height:1.5}.preview-pane{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}.preview-header{display:flex;align-items:center;justify-content:space-between}.preview-header h2{margin:0;font-size:18px}.preview-stage{position:relative;flex:1;min-height:620px;overflow:auto;padding:16px;border:1px solid var(--border);border-radius:22px;background:linear-gradient(145deg,#fbfbfd,#f0f2f7);box-shadow:var(--shadow)}.preview-empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:#a1a5af;pointer-events:none}.preview-empty.hidden{display:none}.empty-icon{width:66px;height:66px;display:grid;place-items:center;border-radius:20px;background:#e9ebf2;font-size:28px}.preview-empty strong{margin:10px 0 6px;color:#676c78}.task-panel{position:relative;z-index:1}.task-panel-head{display:flex;align-items:center;justify-content:space-between;padding:12px 13px;border:1px solid var(--border);border-radius:13px;background:#fff}.note,.task-meta{color:var(--muted);font-size:11px}.task-card,.job{margin:10px 0;padding:12px;border:1px solid var(--border);border-radius:13px;background:#fff}.task-head{display:grid;grid-template-columns:32px 1fr auto;gap:10px;align-items:center}.task-spin{width:30px;height:30px;border:3px solid #e0e4ef;border-top-color:var(--brand);border-radius:50%;animation:spin .9s linear infinite}.task-spin.done{border-color:#78ae99;animation:none}.task-spin.err{border-color:#cc8178;animation:none}.task-name{font-size:13px;font-weight:850}.task-time{font-size:12px;font-weight:850;font-variant-numeric:tabular-nums}.task-result{margin-top:10px}.task-result img,.job img{display:block;width:100%;max-height:720px;object-fit:contain;border-radius:10px;background:#f1f2f5}.dl{display:block;width:100%;min-height:44px;margin-top:7px;padding:10px;border:0;border-radius:9px;background:#f0f2f8;color:#5d6474;font-weight:750;text-align:center;text-decoration:none;cursor:pointer}.library-overlay{display:none;position:fixed;inset:0;z-index:100;padding:74px 20px 20px;background:rgba(25,28,38,.28)}.library-overlay.open{display:flex;justify-content:flex-end}.library-panel{width:min(460px,100%);height:100%;display:flex;flex-direction:column;overflow:hidden;border-radius:20px;background:#fff;box-shadow:0 22px 60px rgba(25,29,46,.2)}.library-header{display:flex;align-items:center;justify-content:space-between;flex:0 0 auto;padding:18px;border-bottom:1px solid var(--border)}.library-header h2{margin:0;font-size:18px}.library-scroll{flex:1;min-height:0;overflow:auto;padding:0 18px 18px}.close{width:44px;height:44px;border:0;border-radius:10px;background:#f1f3f8;cursor:pointer}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:1020px){.studio-grid{grid-template-columns:minmax(330px,410px) minmax(0,1fr);padding:16px}.topbar{padding:0 16px;gap:14px}.brand span:last-child{display:none}}
@media(max-width:820px){body{height:auto;overflow:auto}.app-shell{height:auto;overflow:visible}.topbar{height:auto;min-height:60px;flex-wrap:wrap;padding:10px 12px}.brand span:last-child{display:inline}.topnav{order:3;width:100%}.topbar-tools{margin-left:auto}.topbar-action{min-width:52px;min-height:44px;padding:0 9px;font-size:11px}.studio-grid{grid-template-columns:1fr;height:auto;padding:12px}.studio-grid{padding-bottom:calc(118px + env(safe-area-inset-bottom))}.creation-scroll{overflow:visible;padding:14px}.creation-footer{position:fixed;left:12px;right:12px;bottom:calc(8px + env(safe-area-inset-bottom));z-index:88;padding:12px 14px 14px;border:1px solid var(--border);border-radius:16px;background:rgba(255,255,255,.96);box-shadow:0 14px 40px rgba(29,35,60,.18);backdrop-filter:blur(16px)}.preview-stage{min-height:460px}.library-overlay{padding:62px 8px 8px}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
'''

BODY=r'''
<div class="app-shell"><header class="topbar"><a class="brand" href="/"><span class="brand-mark">JT</span><span>JT 灵感工作台</span></a><nav class="topnav"><a class="topnav-link" href="/">创作台</a><a class="topnav-link" href="/original-sketch">原始铅绘</a><a class="topnav-link" href="/original-graphic">原始古风</a><a class="topnav-link active" href="/realcomic">漫画转真人</a><a class="topnav-link" href="/realism">真人化工作流</a><a class="topnav-link" href="/video">视频</a></nav><div class="topbar-tools"><button class="topbar-action" id="favOpen">♥ 收藏</button><button class="topbar-action" id="histOpen">⌛ 历史</button></div></header>
<main class="studio-grid"><aside class="creation-pane"><div class="creation-scroll"><div class="pane-heading"><span class="eyebrow">AI APP</span><h1>漫画转真人</h1></div><div class="provider-note"><b>Anime to Live-Action V6 Speed</b><br>第三方 RunningHub AI 应用。上传内容会发送至RunningHub处理；结果由该应用生成。</div><label class="field-label" for="sourceFile">二次元图</label><div class="drop" id="sourceDrop" tabindex="0" role="button" aria-label="选择二次元图片"><div class="drop-copy"><strong>点击或拖入图片</strong><small>PNG / JPEG / WebP，最大30MB</small></div><img id="sourcePreview" alt="待转换二次元图预览"></div><input id="sourceFile" type="file" accept="image/png,image/jpeg,image/webp"><div class="upload-state" id="uploadState" aria-live="polite">尚未选择图片</div><label class="field-label" for="requirements">别的要求</label><textarea id="requirements" placeholder="可选：保留构图、保持服装、自然肤质、去除文字等"></textarea><div class="hint">可补充转换要求；留空也可以运行。</div></div><div class="creation-footer"><button class="primary" id="realcomicGenerate" aria-busy="false" disabled><span>请先上传图片</span></button><div class="status" id="generateStatus" aria-live="polite"></div></div></aside>
<section class="preview-pane"><div class="preview-header"><h2>转换结果</h2><span class="note">任务卡独立运行，切换页面后可恢复</span></div><div class="preview-stage"><div class="preview-empty" id="previewEmpty"><div class="empty-icon">◫</div><strong>真人化结果将在这里显示</strong><span>先上传一张二次元或漫画人物图</span></div><section class="task-panel"><div class="task-panel-head"><b>任务中心</b><span class="note" id="taskCount">0个任务</span></div><div id="taskList"></div></section></div></section></main>
<div class="library-overlay" id="histOverlay"><div class="library-panel"><div class="library-header"><h2>漫画转真人历史</h2><button class="close">×</button></div><div class="library-scroll"><div id="histList"></div></div></div></div><div class="library-overlay" id="favOverlay"><div class="library-panel"><div class="library-header"><h2>漫画转真人收藏</h2><button class="close">×</button></div><div class="library-scroll"><div id="favList"></div></div></div></div></div>
'''

JS=r'''
const api=async(path,opt={})=>{const response=await fetch(path,opt);let data={};try{data=await response.json()}catch{}if(!response.ok){const error=new Error(data.error||('HTTP '+response.status));error.data=data;throw error}return data};
const ACTIVE_KEY='jt-active-realcomic-cloud',CREATOR_ROUTES=['/','/original-sketch','/original-graphic','/realcomic','/realism','/video'];let selectedFile=null,uploadedFileName='',uploading=false,submitting=false;const tasks=new Map();
function blobToB64(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)})}
function setUploadState(text,kind=''){uploadState.textContent=text;uploadState.className='upload-state '+kind}function updateGenerateAvailability(){const ready=!!uploadedFileName&&!uploading&&!submitting;realcomicGenerate.disabled=!ready;realcomicGenerate.querySelector('span').textContent=ready?'开始漫画转真人':(uploading?'图片上传中':'请先上传图片')}
async function acceptFile(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){setUploadState('只支持PNG、JPEG或WebP图片','err');updateGenerateAvailability();return}if(file.size>30*1024*1024){setUploadState('图片超过30MB限制','err');updateGenerateAvailability();return}selectedFile=file;uploadedFileName='';sourcePreview.src=URL.createObjectURL(file);sourceDrop.classList.add('has-image');uploading=true;updateGenerateAvailability();setUploadState('正在上传至RunningHub…');try{const data=await blobToB64(file);const result=await api('/api/realcomic-upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,data})});uploadedFileName=result.fileName;setUploadState('✓ '+file.name+' 已上传','ok')}catch(error){setUploadState('上传失败：'+error.message,'err')}finally{uploading=false;updateGenerateAvailability()}}
sourceDrop.onclick=()=>sourceFile.click();sourceDrop.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();sourceFile.click()}};sourceDrop.ondragover=event=>{event.preventDefault();sourceDrop.classList.add('drag')};sourceDrop.ondragleave=()=>sourceDrop.classList.remove('drag');sourceDrop.ondrop=event=>{event.preventDefault();sourceDrop.classList.remove('drag');acceptFile(event.dataTransfer.files[0])};sourceFile.onchange=()=>acceptFile(sourceFile.files[0]);
function fmtTime(seconds){seconds=Math.max(0,Math.floor(seconds));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function statusText(job){const phase=job.provider_status||job.status;if(job.status==='done')return '✓ 转换完成';if(job.status==='error')return '✗ '+(job.error||'转换失败');if(phase==='SUBMITTING')return '正在提交';if(phase==='QUEUED')return '排队中';if(phase==='RUNNING')return '转换中';if(phase==='FINALIZING')return '正在整理结果';return phase||'处理中'}
function addTaskCard(jobId,name='漫画转真人'){if(tasks.has(jobId))return tasks.get(jobId);previewEmpty.classList.add('hidden');const card=document.createElement('article');card.className='task-card';card.dataset.jobId=jobId;card.innerHTML='<div class="task-head"><div class="task-spin"></div><div><div class="task-name">'+name+'</div><div class="task-meta">任务号：'+jobId+' · 等待状态</div></div><div class="task-time">00:00</div></div><div class="task-result"></div>';taskList.prepend(card);const task={card,meta:card.querySelector('.task-meta'),spin:card.querySelector('.task-spin'),time:card.querySelector('.task-time'),result:card.querySelector('.task-result'),started:Date.now(),timer:setInterval(()=>task.time.textContent=fmtTime((Date.now()-task.started)/1000),500)};tasks.set(jobId,task);taskCount.textContent=tasks.size+'个任务';return task}
function renderResults(job,container){container.innerHTML='';(job.images||[]).forEach((image,index)=>{const item=document.createElement('div');item.className='job';item.innerHTML='<div class="note">第三方 RunningHub AI 应用 · 任务号：'+job.id+'</div><img loading="lazy" decoding="async" src="'+(image.preview_url||image.url)+'" alt="漫画转真人结果"><button class="dl favorite">♥ 收藏此结果</button><a class="dl" href="'+image.url+'" target="_blank" rel="noopener">⬇ 下载原图</a>';item.querySelector('.favorite').onclick=async event=>{event.target.disabled=true;try{await api('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:job.id,image_index:index})});event.target.textContent='✓ 已收藏'}catch(error){event.target.disabled=false;event.target.textContent='收藏失败：'+error.message}};container.appendChild(item)})}
async function pollTask(jobId){const task=addTaskCard(jobId);let failures=0;realcomicGenerate.disabled=true;realcomicGenerate.setAttribute('aria-busy','true');realcomicGenerate.querySelector('span').textContent='转换任务运行中';while(tasks.has(jobId)){try{const job=await api('/api/job/'+jobId);failures=0;task.meta.textContent='任务号：'+jobId+' · '+statusText(job);if(job.status==='done'||job.status==='error'){clearInterval(task.timer);task.timer=null;task.time.textContent=fmtTime(job.elapsed||0);task.spin.className='task-spin '+(job.status==='done'?'done':'err');sessionStorage.removeItem(ACTIVE_KEY);if(job.status==='done')renderResults(job,task.result);realcomicGenerate.setAttribute('aria-busy','false');updateGenerateAvailability();return job}}catch(error){failures++;task.meta.textContent='任务号：'+jobId+' · 状态连接中断，正在重试（'+failures+'/6）';if(failures>=6){task.spin.className='task-spin err';task.meta.textContent='任务号：'+jobId+' · 暂时无法获取状态，请稍后刷新恢复';realcomicGenerate.setAttribute('aria-busy','false');updateGenerateAvailability();return}}await new Promise(resolve=>setTimeout(resolve,failures?3000:1800))}}
async function submitWithRetry(body){let last;for(let attempt=0;attempt<2;attempt++){try{return await api('/api/ai-app-generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}catch(error){last=error;if(error.data?.running_job)throw error;if(attempt===0)await new Promise(resolve=>setTimeout(resolve,1400))}}throw last}
realcomicGenerate.onclick=async()=>{if(submitting||realcomicGenerate.getAttribute('aria-busy')==='true')return;if(uploading){generateStatus.textContent='图片仍在上传，请稍候';return}if(!selectedFile||!uploadedFileName){generateStatus.textContent='请先选择并完成上传二次元图';return}submitting=true;realcomicGenerate.disabled=true;realcomicGenerate.setAttribute('aria-busy','true');realcomicGenerate.querySelector('span').textContent='正在提交';generateStatus.textContent='正在提交…';const client_request_id='realcomic-'+Date.now()+'-'+Math.random().toString(36).slice(2);const body={workflow:'realcomic',media:{source_image:uploadedFileName},params:{requirements:requirements.value.trim()},client_request_id,selection_snapshot:{source_page:'realcomic',requirements:requirements.value.trim(),source_filename:selectedFile.name,generation_backend:'cloud'}};let accepted=false;try{const result=await submitWithRetry(body);accepted=true;sessionStorage.setItem(ACTIVE_KEY,result.job_id);addTaskCard(result.job_id);generateStatus.textContent=(result.deduplicated?'已恢复':'已提交')+'，任务号：'+result.job_id;pollTask(result.job_id)}catch(error){const running=error.data?.running_job;generateStatus.textContent='提交失败：'+error.message+(running?'；正在运行任务号：'+running:'')}finally{submitting=false;if(!accepted){realcomicGenerate.disabled=false;realcomicGenerate.setAttribute('aria-busy','false');realcomicGenerate.querySelector('span').textContent='开始漫画转真人'}}};
async function restoreTask(){const jobId=sessionStorage.getItem(ACTIVE_KEY);if(!jobId)return;generateStatus.textContent='正在进行任务恢复，任务号：'+jobId;try{await pollTask(jobId)}catch(error){generateStatus.textContent='任务恢复失败：'+error.message+'；任务号：'+jobId}}
async function history(){histList.innerHTML='加载中…';try{const jobs=(await api('/api/jobs')).filter(job=>job.workflow==='realcomic');histList.innerHTML='';if(!jobs.length)histList.innerHTML='<div class="job note">暂无漫画转真人历史</div>';jobs.forEach(job=>{const card=document.createElement('div');card.className='job';card.innerHTML='<b>'+statusText(job)+'</b><div class="note">任务号：'+job.id+' · '+(job.elapsed||'—')+'秒</div><button class="dl">查看结果</button>';card.querySelector('button').onclick=()=>renderResults(job,card);histList.appendChild(card)})}catch(error){histList.innerHTML='<div class="job">历史加载失败：'+error.message+'</div>'}}
async function favorites(){favList.innerHTML='加载中…';try{const items=(await api('/api/favorites')).filter(item=>item.selection_snapshot?.source_page==='realcomic');favList.innerHTML='';if(!items.length)favList.innerHTML='<div class="job note">暂无漫画转真人收藏</div>';items.forEach(item=>{const card=document.createElement('div');card.className='job';card.innerHTML='<div class="note">'+(item.selection_snapshot?.requirements||'漫画转真人')+'</div><img loading="lazy" decoding="async" src="'+(item.preview_url||item.image_url)+'"><a class="dl" href="'+item.image_url+'" target="_blank">⬇ 下载原图</a>';favList.appendChild(card)})}catch(error){favList.innerHTML='<div class="job">收藏加载失败：'+error.message+'</div>'}}
histOpen.onclick=()=>{histOverlay.querySelector('.library-scroll').scrollTop=0;histOverlay.classList.add('open');history()};favOpen.onclick=()=>{favOverlay.querySelector('.library-scroll').scrollTop=0;favOverlay.classList.add('open');favorites()};document.querySelectorAll('.library-overlay .close').forEach(button=>button.onclick=()=>button.closest('.library-overlay').classList.remove('open'));document.querySelectorAll('.library-overlay').forEach(overlay=>overlay.onclick=event=>{if(event.target===overlay)overlay.classList.remove('open')});
function scheduleRoutePrefetch(){const connection=navigator.connection||{};if(connection.saveData||/2g/.test(connection.effectiveType||''))return;const load=href=>{if(href===location.pathname||document.querySelector('link[rel="prefetch"][href="'+href+'"]'))return;const link=document.createElement('link');link.rel='prefetch';link.as='document';link.href=href;document.head.appendChild(link)};document.querySelectorAll('.topnav-link').forEach(anchor=>anchor.addEventListener('pointerenter',()=>load(anchor.getAttribute('href')),{once:true}));const idle=()=>CREATOR_ROUTES.filter(x=>x!==location.pathname).slice(0,2).forEach(load);'requestIdleCallback'in window?requestIdleCallback(idle,{timeout:2500}):setTimeout(idle,1800)}scheduleRoutePrefetch();restoreTask();
'''

html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>漫画转真人 · JT 灵感工作台</title><style>'+CSS+'</style></head><body>'+BODY+'<script>'+JS+'</script></body></html>'
OUT.write_text(html,encoding='utf8')
print(OUT,OUT.stat().st_size)
